package org.firstinspires.ftc.teamcode.subsystem.control;

import com.bylazar.configurables.annotations.Configurable;

import java.io.ByteArrayOutputStream;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;

/**
 * The HIVE shot map (drag + spin simulation, 30686_render/shooter_analysis) as a lookup table: for every launch
 * position on a 2 in grid and each cell, the launch angle and exit speed that score, flight time to the window and
 * how much exit-speed error the shot tolerates. Data is in {@link HiveAimTableData}, generated by
 * tools/export_hive_aim_table.py.
 *
 * <p>Positions are the shooter's release point (the turret axis) in Pedro inches. Exit speeds are the ball's speed
 * leaving the hood, m/s, robot standing still.
 */
@Configurable
public final class HiveAimTable {
    /** Neighbouring grid spots are blended only when their launch angles are this close, degrees. Across a bigger
     *  jump (e.g. lob vs direct shot) the nearest spot is used instead, so the blend never invents a shot. */
    public static double MAX_BLEND_SPREAD_DEG = 4.0;
    /** A position further than this outside the grid is reported as not scoring, inches. */
    public static double OFF_GRID_MARGIN_IN = 2.0;

    public enum Cell {
        RED_AUD, RED_FAR, BLUE_AUD, BLUE_FAR;

        public static Cell of(boolean red, boolean far) {
            if (red) return far ? RED_FAR : RED_AUD;
            return far ? BLUE_FAR : BLUE_AUD;
        }
    }

    /** One lookup result. Reused by the caller to avoid allocating every loop. */
    public static final class Shot {
        public double launchDeg;
        public double speedMps;
        public double flightSec;
        /** Exit speed error the shot still scores with, +/- m/s. */
        public double halfWindowMps;
        /** The map has a scoring shot here. False: values are copied from the nearest scoring spot. */
        public boolean valid;
        /** Scores only with the other HIVE tilted one particular way. */
        public boolean dependsOnOtherHive;
        /** Blended from four grid spots (false: nearest spot). */
        public boolean blended;
    }

    private static final int FLAG_VALID = 1, FLAG_OTHER_HIVE = 2;

    private static short[] launch;   // deg * 100
    private static char[] speed;     // mm/s
    private static char[] flight;    // ms
    private static char[] half;      // mm/s
    private static byte[] flags;
    private static String loadError = null;

    private HiveAimTable() {}

    /** Decodes the table. Called lazily; call at init to keep the ~10 ms decode out of the first loop. */
    public static synchronized boolean load() {
        if (launch != null) return true;
        if (loadError != null) return false;
        try {
            byte[] raw = inflate(base64(HiveAimTableData.packed()), HiveAimTableData.RAW_BYTES);
            int n = raw.length / HiveAimTableData.RECORD_BYTES;
            int expected = Cell.values().length * HiveAimTableData.N * HiveAimTableData.N;
            if (n != expected) throw new IllegalStateException("table has " + n + " records, expected " + expected);
            short[] l = new short[n];
            char[] s = new char[n], f = new char[n], h = new char[n];
            byte[] fl = new byte[n];
            for (int i = 0, p = 0; i < n; i++, p += HiveAimTableData.RECORD_BYTES) {
                l[i] = (short) (((raw[p] & 0xff) << 8) | (raw[p + 1] & 0xff));
                s[i] = (char) (((raw[p + 2] & 0xff) << 8) | (raw[p + 3] & 0xff));
                f[i] = (char) (((raw[p + 4] & 0xff) << 8) | (raw[p + 5] & 0xff));
                h[i] = (char) (((raw[p + 6] & 0xff) << 8) | (raw[p + 7] & 0xff));
                fl[i] = raw[p + 8];
            }
            speed = s; flight = f; half = h; flags = fl;
            launch = l;
            return true;
        } catch (RuntimeException | DataFormatException e) {
            loadError = e.toString();
            return false;
        }
    }

    public static boolean loaded() { return launch != null; }
    public static String loadError() { return loadError; }

    /**
     * Shot for a release point (Pedro inches) at a cell. Returns false only if the table failed to load.
     * {@code out.valid} says whether the map has a scoring shot there.
     */
    public static boolean lookup(Cell cell, double x, double y, Shot out) {
        if (!load()) return false;
        final int n = HiveAimTableData.N;
        final double x0 = HiveAimTableData.X0, dx = HiveAimTableData.DX, xMax = x0 + (n - 1) * dx;
        boolean offGrid = x < x0 - OFF_GRID_MARGIN_IN || x > xMax + OFF_GRID_MARGIN_IN
                || y < x0 - OFF_GRID_MARGIN_IN || y > xMax + OFF_GRID_MARGIN_IN;
        double fx = clamp((x - x0) / dx, 0, n - 1);
        double fy = clamp((y - x0) / dx, 0, n - 1);
        int ix0 = Math.min((int) fx, n - 2), iy0 = Math.min((int) fy, n - 2);
        double tx = fx - ix0, ty = fy - iy0;
        int base = cell.ordinal() * n * n;
        int i00 = base + iy0 * n + ix0, i01 = i00 + 1, i10 = i00 + n, i11 = i10 + 1;

        double l00 = launch[i00] / 100.0, l01 = launch[i01] / 100.0, l10 = launch[i10] / 100.0, l11 = launch[i11] / 100.0;
        double spread = Math.max(Math.max(l00, l01), Math.max(l10, l11)) - Math.min(Math.min(l00, l01), Math.min(l10, l11));
        int f00 = flags[i00], f01 = flags[i01], f10 = flags[i10], f11 = flags[i11];
        boolean sameValidity = (f00 & FLAG_VALID) == (f01 & FLAG_VALID) && (f00 & FLAG_VALID) == (f10 & FLAG_VALID)
                && (f00 & FLAG_VALID) == (f11 & FLAG_VALID);

        if (sameValidity && spread <= MAX_BLEND_SPREAD_DEG) {
            double w00 = (1 - tx) * (1 - ty), w01 = tx * (1 - ty), w10 = (1 - tx) * ty, w11 = tx * ty;
            out.launchDeg = w00 * l00 + w01 * l01 + w10 * l10 + w11 * l11;
            out.speedMps = (w00 * speed[i00] + w01 * speed[i01] + w10 * speed[i10] + w11 * speed[i11]) / 1000.0;
            out.flightSec = (w00 * flight[i00] + w01 * flight[i01] + w10 * flight[i10] + w11 * flight[i11]) / 1000.0;
            out.halfWindowMps = (w00 * half[i00] + w01 * half[i01] + w10 * half[i10] + w11 * half[i11]) / 1000.0;
            out.valid = (f00 & FLAG_VALID) != 0;
            out.dependsOnOtherHive = ((f00 | f01 | f10 | f11) & FLAG_OTHER_HIVE) != 0;
            out.blended = true;
        } else {
            int i = base + (int) Math.round(fy) * n + (int) Math.round(fx);
            out.launchDeg = launch[i] / 100.0;
            out.speedMps = speed[i] / 1000.0;
            out.flightSec = flight[i] / 1000.0;
            out.halfWindowMps = half[i] / 1000.0;
            out.valid = (flags[i] & FLAG_VALID) != 0;
            out.dependsOnOtherHive = (flags[i] & FLAG_OTHER_HIVE) != 0;
            out.blended = false;
        }
        if (offGrid) out.valid = false;
        return true;
    }

    private static double clamp(double v, double lo, double hi) { return Math.max(lo, Math.min(hi, v)); }

    private static byte[] inflate(byte[] data, int size) throws DataFormatException {
        Inflater inf = new Inflater();
        try {
            inf.setInput(data);
            ByteArrayOutputStream out = new ByteArrayOutputStream(size);
            byte[] buf = new byte[8192];
            while (!inf.finished()) {
                int k = inf.inflate(buf);
                if (k == 0 && (inf.needsInput() || inf.needsDictionary())) throw new DataFormatException("truncated table");
                out.write(buf, 0, k);
            }
            return out.toByteArray();
        } finally {
            inf.end();
        }
    }

    /** Plain base64 decoder: java.util.Base64 needs Android API 26 and the Control Hub runs API 25. */
    private static byte[] base64(String s) {
        int[] val = new int[128];
        java.util.Arrays.fill(val, -1);
        String alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        for (int i = 0; i < 64; i++) val[alpha.charAt(i)] = i;
        ByteArrayOutputStream out = new ByteArrayOutputStream(s.length() * 3 / 4);
        int acc = 0, bits = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '=') break;
            int v = c < 128 ? val[c] : -1;
            if (v < 0) continue;
            acc = ((acc << 6) | v) & 0xFFFFFF;
            bits += 6;
            if (bits >= 8) {
                bits -= 8;
                out.write((acc >> bits) & 0xff);
            }
        }
        return out.toByteArray();
    }
}
